/**
 * Wave R2 markets and the ORRY paymaster (lane L3, `docs/updates/L3-R2-SPEC.md`): release names, burn sources, the
 * EIP-712 limit order, and the JSON shapes of every `/v1/r2/` route. Browser-safe: the web app imports this file. The
 * contract ABIs at the end are generated by `scripts/r2-gen-abi.mjs` from `contracts/out`; do not edit that block by hand.
 */

/** Release switch names this lane adds (`paymaster` already existed in `RELEASE_FEATURES`). */
export const R2_FEATURES = ["predict", "limit-orders", "shield"] as const;
export type R2Feature = (typeof R2_FEATURES)[number] | "paymaster";

/** `IOrryBurnEvents.Burned` sources of this lane (lane-numbered range 30 to 39). */
export const R2_BURN_SOURCES = { predictCreate: 30, predictFee: 31, limitFee: 32, paymasterPremium: 33 } as const;

/** Which feature opens which route; a held feature's routes answer the 404 of an unknown route. */
export const R2_ROUTE_FEATURE = {
  "GET /v1/r2/predict": "predict",
  "GET /v1/r2/predict/:market": "predict",
  "GET /v1/r2/limit-orders": "limit-orders",
  "POST /v1/r2/limit-orders": "limit-orders",
  "GET /v1/r2/paymaster": "paymaster",
  "GET /v1/r2/shield": "shield",
} as const satisfies Record<string, R2Feature>;

/** Never held: what a user needs to see their positions, balances and stored orders. */
export const R2_NEVER_HELD_ROUTES = ["GET /v1/r2/accounts/:address", "GET /v1/r2/shield/events"] as const;

// ------------------------------------------------------------------ prediction markets

export type PredictStatus = "open" | "locked" | "closed" | "yes" | "no" | "refund";

export interface PredictMarketView {
  market: string;
  feed: string;
  /** Stock token whose corporate actions refund the market, or null for a non-stock feed. */
  asset: string | null;
  /** The feed's own description, for example "TSLA / USD". */
  label: string;
  /** Strike in the feed's decimals, as a decimal string, and those decimals. */
  strike: string;
  decimals: number;
  closeTime: number;
  lockTime: number;
  createdAt: number;
  /** open (staking), locked (staking closed, before the close), closed (waiting for settlement), or the outcome. */
  status: PredictStatus;
  yesPool: string;
  noPool: string;
  stakers: number;
  settlePrice: string | null;
  feeBps: number;
  minStake: string;
  /** Latest feed answer and its time, for the page's live line; null when unreadable. */
  latest: { answer: string; updatedAt: number } | null;
}

export interface PredictMarketsResponse {
  markets: PredictMarketView[];
  chainTime: number;
  updatedAt: string;
}

export interface PredictMarketResponse extends PredictMarketView {
  chainTime: number;
  updatedAt: string;
}

export interface PredictPosition {
  market: string;
  yes: string;
  no: string;
  claimed: boolean;
  /** USDG paid at claim, when claimed. */
  payout: string | null;
}

// ------------------------------------------------------------------ limit orders

/** EIP-712 domain and type of a limit order, as `LimitOrderBook.hashOrder`. */
export const LIMIT_ORDER_DOMAIN = { name: "Orrery Limit Orders", version: "1" } as const;
export const LIMIT_ORDER_TYPES = {
  Order: [
    { name: "owner", type: "address" },
    { name: "asset", type: "address" },
    { name: "sellAsset", type: "bool" },
    { name: "amountIn", type: "uint256" },
    { name: "limitPrice", type: "uint256" },
    { name: "tipBps", type: "uint16" },
    { name: "payFeeInOrry", type: "bool" },
    { name: "nonce", type: "uint256" },
    { name: "expiry", type: "uint64" },
  ],
} as const;

export interface LimitOrderInput {
  owner: string;
  asset: string;
  sellAsset: boolean;
  amountIn: string;
  limitPrice: string;
  tipBps: number;
  payFeeInOrry: boolean;
  nonce: string;
  expiry: number;
}

export type LimitOrderStatus = "open" | "filled" | "cancelled" | "expired";

export interface LimitOrderView extends LimitOrderInput {
  hash: string;
  symbol: string;
  status: LimitOrderStatus;
  createdAt: string;
  fill: { amountOut: string; usdgFee: string; orryFee: string; tip: string; tx: string } | null;
}

export interface LimitOrdersResponse {
  orders: LimitOrderView[];
  book: string;
  feeBps: number;
  maxDeviationBps: number;
  updatedAt: string;
}

export interface LimitOrderSubmitResponse {
  hash: string;
  status: LimitOrderStatus;
}

// ------------------------------------------------------------------ paymaster

export interface PaymasterView {
  paymaster: string;
  entryPoint: string;
  version: "0.7" | "0.8";
  premiumBps: number;
  maxCostWei: string;
  /** ORRY base units per 1e18 wei of gas, cached for validation, and when; null before the first refresh. */
  rate: string | null;
  rateAt: number | null;
  maxRateAge: number;
}

export interface PaymasterResponse {
  paymasters: PaymasterView[];
  updatedAt: string;
}

// ------------------------------------------------------------------ shield

export interface ShieldInfo {
  pool: string;
  asset: string;
  depositFeeBps: number;
  withdrawFeeBps: number;
  /** Notes in the tree (deposits and outputs). */
  leaves: number;
  deposits: number;
  updatedAt: string;
}

/** A pool event in chain order, bigints as decimal strings (the client's `eventFromJson`). */
export type ShieldEventJson =
  | { type: "Deposited"; depositor: string; amount: string; fee: string; secretCommit: string; commitment: string; leafIndex: number; encryptedNote: string }
  | { type: "NewCommitment"; commitment: string; leafIndex: number; encryptedNote: string }
  | { type: "NewNullifier"; nullifier: string };

/** `GET /v1/r2/shield/events?after=<cursor>`: never held, so notes can always be found and withdrawn. */
export interface ShieldEventsResponse {
  events: ShieldEventJson[];
  /** Pass back as `after` to continue; null when nothing has been indexed yet. */
  cursor: string | null;
  /** True when the page reached the indexer's height. */
  done: boolean;
}

// ------------------------------------------------------------------ account (never held)

export interface R2AccountResponse {
  address: string;
  predict: PredictPosition[];
  limitOrders: LimitOrderView[];
  /** Prepaid ORRY per paymaster. */
  gas: { paymaster: string; balance: string; ops: number; charged: string }[];
  updatedAt: string;
}

